Suppose that $\mu_0^2 r \lesssim p^{1/2}$, that $\kappa^2 \lesssim p^{1/4}$,  that $\lambda/\sigma \gtrsim \kappa p^{3/4} \sqrt{\log(p)}$, \textcolor{black}{and that $\lambda/\sigma \leq \exp(c p)$ for some small constant $c$}. Let $\mathbf{\widehat{U}}_k^{(t)}$ denote the estimated singular vectors from the output of \texttt{HOOI} (al:tensor-power-iteration) with $t \asymp \textcolor{black}{\log( \frac{\lambda/\sigma}{C \kappa \sqrt{p\log(p)}}})$
iterations, initialized via al:dd.  Suppose $\mathbf{T}_k = \mathcal{M}_k(\mathcal{T})$ has rank $r_k$ singular value decomposition ${\mathbf{U}}_k \mathbf{\Lambda}_k \mathbf{V}_k^{\top}$. 
Denote $\mathbf{Z}_k = \mathcal{M}_k(\mathcal{Z})$.
Then there exists an event $\mathcal{E}_{\mathrm{Theorem} \ 14}$ with $\mathbb{P}(\mathcal{E}_{\mathrm{Theorem} \ 14}) \geq 1 - O(p^{-9})$ such that on this event it holds that
 \begin{align*}
     \mathbf{\widehat{U}}_k^{(t)} ( \mathbf{W}_k^{(t)})^{\top} - {\mathbf{U}}_k &= \mathbf{Z}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1} + \mathbf{\Psi}^{(k)},
 \end{align*}
 where 
 \begin{align*}
     \big\| \mathbf{\Psi}^{(k)} \big\|_{2,\infty} &\lesssim \frac{\sigma^2 \kappa^2 \mu_0^2 \log(p) r \sqrt{p}}{\lambda^2} + \frac{\mu_0 r \kappa}{\lambda \sqrt{p}}.
 \end{align*}

Instate the conditions of 14.    Let $\Sigma_k^{(m)}$ denote the diagonal matrix of dimension  $p_{-k} \times p_{-k}$, where the diagonal entries consist of the variances of $\mathcal{Z}_{mbc}$ if $k = 1$, $\mathcal{Z}_{amc}$ if $k = 2$, and $\mathcal{Z}_{abm}$ if $k = 3$.  Define
  \begin{align*}
     \mathbf{\Gamma}^{(m)}_k &\coloneqq \mathbf{\Lambda}_k^{-1} \mathbf{V}_k^{\top} \Sigma^{(m)} \mathbf{V}_k \mathbf{\Lambda}_k^{-1}.
 \end{align*}
 Let $\mathcal{A}$ denote the collection of all convex sets in  $\mathbb{R}^{r_k}$, and let $Z$  be an $r_k$-dimensional Gaussian random variable with the identity covariance matrix. Then it holds that
 \begin{align*}
      \sup_{A \in \mathcal{A}} | &\mathbb{P}\bigg\{   \big( \mathbf{\Gamma}^{(m)}_k \big)^{-1/2}  \bigg( \mathbf{\widehat{U}}_k^{(t)} (\mathbf{W}_k^{(t)})^{\top} - {\mathbf{U}}_k \bigg)_{m\cdot} \in A \bigg\} - \mathbb{P} \{ Z \in A \} | \\
      &\lesssim \mu_0 \frac{r^2}{p} + \frac{\sigma\kappa^3 \mu_0^2 \log(p) r^{3/2} \sqrt{p}}{\lambda}  + \frac{\mu_0 r^{3/2} \kappa }{ \sqrt{p}}.
 \end{align*}
 Therefore, asymptotic normality holds as long as $\kappa^2 \mu_0^2 r^{3/2} = o\big(p^{1/4}/\sqrt{\log(p)}\big)$. Furthermore, when $\kappa$ and $\mu_0$ are bounded, a sufficient condition for asymptotic normality is that $r = o(p^{1/6}/\log(p))$.

Instate the conditions of 14, and suppose further that \begin{align*}
 \kappa^2 \mu_0^2 r^{3/2} \sqrt{\log(p)} \lesssim p^{1/4}.
\end{align*}
Let $\Sigma_1^{(m)} \in \mathbb{R}^{p_2p_3 \times p_2p_3}$ be the diagonal matrix whose $(a-1)p_3 + b$'th entry is the variance of the random variable $\mathcal{Z}_{mab}$, and let $\Sigma_2^{(m)}$ and $\Sigma_{3}^{(m)}$ be defined similarly.  Assume that
\begin{align*}
   \| e_{(j-1)p_3 + k}^{\top} &\mathbf{V}_1 \|^2 + \|e_{(k-1)p_1 + i} \mathbf{V}_2  \|^2 + \| e_{(i-1)p_2 + j} \mathbf{V}_3\|^2 \\
   &\gg \max\bigg\{\frac{ \kappa^4 \mu_0^6 r^4 \log(p)}{p^{3}} ,\frac{\sigma^2\mu_0^8 \kappa^6 r^{4} \log^2(p)}{\lambda^2 p}\bigg\}.
  \end{align*}
Define 
 \begin{align*}
    s^2_{ijk} &\coloneqq  \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \mathbf{V}_1^{\top} \big(\Sigma^{(i)}\big)^{1/2} \|^2 + \|e_{(k-1)p_1 + i} \mathbf{V}_2 \mathbf{V}_2^{\top}\big(\Sigma^{(j)}\big)^{1/2} \|^2 \\
    &\quad + \| e_{(i-1)p_2 + j} \mathbf{V}_3\mathbf{V}_3^{\top} \big( \Sigma^{(k)} \big)^{1/2}\|^2.
\end{align*}
Let $Z$ denote a standard Gaussian random variable and let $\Phi$ denote its cumulative distribution function. Then it holds that
\begin{align*}
    \sup_{t\in\mathbb{R}} \bigg| \mathbb{P}\bigg\{ \frac{ \mathcal{\widehat T}_{ijk} - \mathcal{T}_{ijk}}{s_{ijk}} \leq t \bigg\} - \Phi(t) \bigg| &= o(1).  
\end{align*}

Instate the conditions of 14. Under the event $\mathcal{E}_{\mathrm{14}}$ it holds that
\begin{align*}
    \mathbf{\widehat{U}}_k^{(t)} (\mathbf{\widehat{U}}_k^{(t)})^{\top} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top} &= {\mathbf{U}}_k \mathbf{\Lambda}_k^{-1} \mathbf{V}_k \mathbf{Z}_k^{\top} + \mathbf{Z}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1} {\mathbf{U}}_k^{\top} + \mathbf{\Phi}^{(k)},
\end{align*}
where
\begin{align*}
    \big\| \mathbf{\Phi}^{(k)} \big\|_{2,\infty} &\lesssim 
    \frac{\sigma^2\kappa^2 \mu_0^3 \log(p) r^{3/2} \sqrt{p}}{\lambda^2}   + \frac{\sigma \mu_0^2 r^{3/2} \kappa}{\lambda \sqrt{p}}
\end{align*}

Instate the conditions of 14, and suppose that
\begin{align*}
    \kappa^2 \mu_0^2 r^{3/2} \sqrt{\log(p)} \lesssim p^{1/4}.
\end{align*}
Then the following bound holds with probability at least $1 - O(p^{-6})$:
\begin{align*}
    \| \mathcal{\widehat T} - \mathcal{T} \|_{\max} &\lesssim \frac{\mu_0\sigma \sqrt{r\log(p)}  }{p}  
    + \frac{\sigma^2 \mu_0^4 \kappa^3 r^3 \log(p)}{\lambda \sqrt{p}} 

\end{align*}
Consequently, when the following condition holds:
\begin{align*}

   \lambda/\sigma \gtrsim  \mu_0^3 \kappa^3 r^{5/2} \sqrt{p\log(p)},
\end{align*}
the bound above reduces to
\begin{align*}
     \| \mathcal{\widehat T} - \mathcal{T} \|_{\max} &\lesssim \frac{ \kappa \sigma \mu_0 \sqrt{r\log(p)}}{p}.
\end{align*}
In particular, this bound holds if $\mu_0 = O(1)$ and $\kappa^3 r^{5/2} = o(p^{1/4})$.

Instate the conditions of 14.   Suppose also that 
 \begin{align}
     \kappa^2 \mu_0^2 r^{3/2}\sqrt{\log(p)} \lesssim p^{1/4}. 
 \end{align}
 In addition, assume that $\mu_0 \frac{r^2}{p} = o(1)$ and that
 \begin{align*}
     \lambda/\sigma \gg  \kappa^3 \mu_0^2 \log^2(p) r^2 \sqrt{p}.
 \end{align*}
 Let $\mathrm{C.R.}^{\alpha}_{k,m}(\mathbf{\widehat{U}}_k)$ denote  the output of al:ci_eigenvector.  Then it holds that
 \begin{align*}
     \mathbb{P}\bigg\{ \bigg( {\mathbf{U}}_k \mathbf{W}_k^{(t)} \bigg)_{m\cdot} \in \mathrm{C.R.}^{\alpha}_{k,m}(\mathbf{\widehat{U}}_k) \bigg\} = 1- \alpha  - o(1).
 \end{align*}

Instate the conditions of 17.  Suppose further that 
\begin{align*}
\left\|e_{(j-1) p_{3}+k}^{\top} \mathbf{V}_{1}\right\|^{2}+\left\|e_{(k-1) p_{1}+i}^{\top} \mathbf{V}_{2}\right\|^{2}+\left\|e_{(i-1) p_{2}+j}^{\top} \mathbf{V}_{3}\right\|^{2} &\gg  \frac{\sigma \mu_0^5 r^3 \kappa^2 \log^{3/2}(p)}{\lambda p^{3/2}}.
\end{align*}
 Let $\mathrm{C.I.}^{\alpha}_{ijk}(\mathcal{\widehat T}_{ijk})$ denote the output of al:ci_entries.  Then it holds that
\begin{align*}
    \mathbb{P}\bigg( \mathcal{T}_{ijk} \in  \mathrm{C.I.}^{\alpha}_{ijk}(\mathcal{\widehat T}_{ijk}) \bigg) = 1- \alpha  - o(1).
\end{align*}

Instate the conditions in 14, and suppose that
\begin{align*}
    \mu_0^2 \kappa^2 r^{3/2} \sqrt{\log(p)} \lesssim p^{1/4}.
\end{align*}
Let $J$ be a given index set with $|J| = o(p^{1/6})$. .  Define the $|J|\times |J|$ matrix $S_J$ via
\begin{align*}
    (S_J)_{\{i,j,k\},\{i',j',k'\}} &\coloneqq  \mathbb{I}_{\{i= i'\}} e_{(j-1)p_3 + k}^{\top}  \mathbf{V}_1 \mathbf{V}_1^{\top} \Sigma_1^{(i)} \mathbf{ V}_1 \mathbf{ V}_1^{\top} e_{(j'-1)p_3 + k'} \\
    &\quad + \mathbb{I}_{\{j= j'\}} e_{(k-1)p_1 + i}^{\top}  \mathbf{ V}_2 \mathbf{ V}_2^{\top} \Sigma_2^{(j)} \mathbf{ V}_2 \mathbf{ V}_2^{\top} e_{(k'-1)p_3 + i'}  \\
    &\quad + \mathbb{I}_{\{k= k'\}} e_{(i-1)p_2 + j}^{\top}  \mathbf{ V}_3 \mathbf{ V}_3^{\top} \Sigma_3^{(k)} \mathbf{ V}_3 \mathbf{ V}_3^{\top} e_{(i'-1)p_2 + '},
\end{align*}
where $\Sigma_k^{(m)}$ is as in 17.  Suppose $S_J$ is invertible, and let $s^2_{\min}$ denote its smallest eigenvalue.  Suppose that 
\begin{align*}
    s_{\min}/\sigma &\gg \max\bigg\{ |J|^{3/2}  \frac{\kappa^2 \mu_0^3 r^{3/2} \sqrt{\log(p)}}{p^{3/2}}, |J|^{3/2} \frac{ \mu_0^4 \kappa^3 r^2 \log(p)}{(\lambda/\sigma) \sqrt{p}}, |J| \frac{ \mu_0^{5/2} r^{3/2} \kappa \log^{3/4}(p)}{(\lambda/\sigma)^{1/2} p^{3/4}}, \\
      &\qquad \qquad \qquad  |J|^{1/6} \frac{\kappa \mu_0^{3/2} r^{3/2} \sqrt{\log(p)}}{p^{4/3}}, |J|^{1/6} \frac{\kappa^{5/3}\mu_0^{3} r^{7/6} \log^{5/6}(p)}{(\lambda/\sigma)^{1/3} p^{5/6}}\bigg\}.
\end{align*}
Let $\mathrm{C.I.}_J^{\alpha}(\mathcal{\widehat T})$ denote the output of al:simultaneousci.






 Then it holds that
\begin{align*}
 \mathbb{P}\bigg\{ \mathrm{Vec}(\mathcal{ T}_J) \in \mathrm{C.I.}_{\alpha}(\mathcal{\widehat T}_J) \bigg\}= 1- \alpha -  o(1).
\end{align*}

Instate the conditions of 14, and suppose that $\kappa ^2 \mu_0^2 r^{3/2} \sqrt{\log(p)} \lesssim p^{1/4}$.  












Suppose that  \begin{align*}
 \min\bigg\{ \|& e_{(j-1)p_3 + k }^{\top} \mathbf{V}_1\|^2, \| e_{(j'-1)p_3 + k'}^{\top} \mathbf{V}_1\|^2, \| e_{(k-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2,\\
 &\| e_{(k'-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2, \| e_{(i-1)p_2 + j}^{\top} \mathbf{V}_3 \|^2, \| e_{(i'-1)p_2 + j'}^{\top} \mathbf{V}_3 \|^2 \bigg\} \\
    &\gg\max\bigg\{ \frac{\kappa \mu_0^2 r^{3/2} \log(p)}{p^3} , \frac{\mu_0^5 r^3 \kappa^2 \log^{3/2}(p)}{(\lambda/\sigma)p^{3/2}}, \frac{\kappa^4 \mu_0^6 r^3 \log(p)}{p^3}, \frac{\mu_0^8 \kappa^6 r^3 \log^2(p)}{(\lambda/\sigma)^2 p} \bigg\} .
    \end{align*} 
     Let $\mathrm{C.I.}^{\alpha}_{\{ijk\},\{i'j'k'\}}( \mathcal{\widehat T}) $ denote the output of al:entrytesting. 
Then it holds that
\begin{align*}
    \frac{\mathcal{\widehat T}_{ijk} - \mathcal{\widehat T}_{i'j'k'} - \big( \mathcal{T}_{ijk} - \mathcal{T}_{i'j'k'}\big)}{\widehat s_{\{ijk\}\{i'j'k'\}}} \to N(0,1).
\end{align*}
